--
-- Name: comparestrings(character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION public.comparestrings(p_str1 character varying, p_str2 character varying) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
declare
    v_pairs1 varchar[];
    v_pairs2 varchar[];
    v_intersection integer;
    v_union integer;
begin
   
    IF (select trim(upper(p_str1))=trim(upper(p_str2))) THEN
	return (1.0);
    END IF;
    
    v_pairs1 := wordletterpairs(upper(p_str1));
    v_pairs2 := wordletterpairs(upper(p_str2));
    v_union := array_length(v_pairs1, 1) + array_length(v_pairs2, 1); 

    v_intersection := array_length(arrayintersect(v_pairs1, v_pairs2), 1);

    return (2.0 * v_intersection / v_union);
end;
$$;


ALTER FUNCTION public.comparestrings(p_str1 character varying, p_str2 character varying) OWNER TO postgres;

