--
-- Name: letterpairs(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION public.letterpairs(p_str character varying) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare

    v_numpairs integer := length(p_str)-1;
    v_pairs varchar[];

begin

    for i in 1 .. v_numpairs loop
        v_pairs[i] := substr(p_str, i, 2);
    end loop;

    return v_pairs;

end;
$$;


ALTER FUNCTION public.letterpairs(p_str character varying) OWNER TO postgres;

--
-- Name: wordletterpairs(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE OR REPLACE FUNCTION public.wordletterpairs(p_str character varying) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
    v_allpairs varchar[];
    v_words varchar[];
    v_pairsinword varchar[];
begin
    v_words := regexp_split_to_array(p_str, '[[:space:]]');

    for i in 1 .. array_length(v_words, 1) loop
        v_pairsinword := letterpairs(v_words[i]);

        if v_pairsinword is not null then
            for j in 1 .. array_length(v_pairsinword, 1) loop
                v_allpairs := v_allpairs || v_pairsinword[j];
            end loop;
        end if;

    end loop;


    return v_allpairs;
end;
$$;


ALTER FUNCTION public.wordletterpairs(p_str character varying) OWNER TO postgres;

