        IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'idx_bas_usuario_perfil_usuario' AND schemaname = 'public') THEN
            CREATE INDEX idx_bas_usuario_perfil_usuario ON bas_usuario_perfil(id_usuario);
        END IF;
        IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'idx_bas_usuario_perfil_perfil' AND schemaname = 'public') THEN
            CREATE INDEX idx_bas_usuario_perfil_perfil ON bas_usuario_perfil(id_perfil);
        END IF;
    END IF;
END $$;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'bas_modulo') THEN
        IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE indexname = 'idx_bas_modulo_outcome' AND schemaname = 'public') THEN
            CREATE INDEX idx_bas_modulo_outcome ON bas_modulo(outcome);
        END IF;
    END IF;
END $$;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'bas_modulo') THEN
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'bas_modulo' AND column_name = 'id_modulo') THEN
            ALTER TABLE bas_modulo ADD CONSTRAINT fk_bas_modulo_pai FOREIGN KEY (id_modulo) REFERENCES bas_modulo(id);
        END IF;
    END IF;
END $$;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'bas_perfil') THEN
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'bas_perfil' AND column_name = 'id_modulo') THEN
            ALTER TABLE bas_perfil ADD CONSTRAINT fk_bas_perfil_modulo FOREIGN KEY (id_modulo) REFERENCES bas_modulo(id);
        END IF;
    END IF;
END $$;

CREATE SEQUENCE IF NOT EXISTS bas_modulo_id_seq START WITH 1 INCREMENT BY 1 NO CYCLE;
